/**
 * Unit tests for BasicSerializerFactory#findSerializerByPrimaryType.
 * Since the method is protected, we use a Test subclass to expose it.
 */
public class BasicSerializerFactory_findSerializerByPrimaryType_TriageGen0Test {

    private TestBasicSerializerFactory factory;
    private SerializerProvider prov;
    private BeanDescription beanDesc;
    private SerializationConfig config;
    private TypeFactory typeFactory;

    // Subclass to access protected method
    private static class TestBasicSerializerFactory extends BasicSerializerFactory {
        protected TestBasicSerializerFactory() {
            super(null);
        }

        @Override
        protected JsonSerializer<?> findOptionalStdSerializer(SerializerProvider prov, JavaType type, BeanDescription beanDesc, boolean staticTyping) throws JsonMappingException {
            return null; // Default to null to test the main logic
        }

        @Override
        protected JsonSerializer<?> buildMapEntrySerializer(SerializationConfig config, JavaType type, BeanDescription beanDesc, boolean staticTyping, JavaType kt, JavaType vt) throws JsonMappingException {
            return mock(JsonSerializer.class);
        }

        @Override
        protected JsonSerializer<?> buildEnumSerializer(SerializationConfig config, JavaType type, BeanDescription beanDesc) throws JsonMappingException {
            return mock(JsonSerializer.class);
        }

        // Mocking customSerializers as it is abstract
        @Override
        protected Iterable<Serializers> customSerializers() {
            return null;
        }
    }

    @Before
    public void setUp() {
        factory = new TestBasicSerializerFactory();
        prov = mock(SerializerProvider.class);
        beanDesc = mock(BeanDescription.class);
        config = mock(SerializationConfig.class);
        typeFactory = TypeFactory.defaultInstance();
        when(prov.getConfig()).thenReturn(config);
    }

    @Test
    public void testFindOptionalStdSerializerFirst() throws JsonMappingException {
        JsonSerializer<?> mockSer = mock(JsonSerializer.class);
        TestBasicSerializerFactory spyFactory = spy(factory);
        doReturn(mockSer).when(spyFactory).findOptionalStdSerializer(any(), any(), any(), anyBoolean());

        JavaType type = typeFactory.constructType(String.class);
        JsonSerializer<?> result = spyFactory.findSerializerByPrimaryType(prov, type, beanDesc, false);

        assertEquals(mockSer, result);
    }

    @Test
    public void testCalendar() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Calendar.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        // Note: CalendarSerializer.instance is internal to Jackson, assuming it exists
        assertNotNull(result);
    }

    @Test
    public void testDate() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Date.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(DateSerializer.instance, result);
    }

    @Test
    public void testMapEntryWithFullTypes() throws JsonMappingException {
        JavaType type = typeFactory.constructMapType(Map.class, String.class, Integer.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testMapEntryWithMissingTypes() throws JsonMappingException {
        // Construct a type that mimics Map.Entry but lacks generic info if possible, 
        // though TypeFactory usually provides unknownType.
        JavaType type = typeFactory.constructType(Map.Entry.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testByteBuffer() throws JsonMappingException {
        JavaType type = typeFactory.constructType(ByteBuffer.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testInetAddress() throws JsonMappingException {
        JavaType type = typeFactory.constructType(InetAddress.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testInetSocketAddress() throws JsonMappingException {
        JavaType type = typeFactory.constructType(InetSocketAddress.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testTimeZone() throws JsonMappingException {
        JavaType type = typeFactory.constructType(TimeZone.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testCharset() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Charset.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(ToStringSerializer.instance, result);
    }

    @Test
    public void testNumberWithoutFormat() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        when(beanDesc.findExpectedFormat(null)).thenReturn(null);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(NumberSerializer.instance, result);
    }

    @Test
    public void testNumberWithStringFormat() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(beanDesc.findExpectedFormat(null)).thenReturn(format);

        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertEquals(ToStringSerializer.instance, result);
    }

    @Test
    public void testNumberWithObjectFormat() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.OBJECT);
        when(beanDesc.findExpectedFormat(null)).thenReturn(format);

        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNull(result);
    }

    @Test
    public void testNumberWithArrayFormat() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Integer.class);
        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.ARRAY);
        when(beanDesc.findExpectedFormat(null)).thenReturn(format);

        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNull(result);
    }

    @Test
    public void testEnum() throws JsonMappingException {
        enum TestEnum { A, B }
        JavaType type = typeFactory.constructType(TestEnum.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testUnknownType() throws JsonMappingException {
        JavaType type = typeFactory.constructType(Object.class);
        JsonSerializer<?> result = factory.findSerializerByPrimaryType(prov, type, beanDesc, false);
        assertNull(result);
    }
}
